var builder = WebApplication.CreateBuilder(args);

builder.Services.AddIdentity<ApplicationUser, IdentityRole>(options =>
{
    options.SignIn.RequireConfirmedAccount = true;
})
.AddEntityFrameworkStores<ApplicationDbContext>()
.AddPasskeySupport();

var app = builder.Build();

app.MapGet("/Account/RegisterPasskey", async (SignInManager<ApplicationUser> signInManager, HttpContext context) =>
{
    var user = await signInManager.GetTwoFactorEnabledUserAsync(context.User);
    if (user is null) return Results.Challenge();
    return Results.Extensions.PasskeyChallenge(user);
})
.WithName("RegisterPasskeyChallenge");

app.MapPost("/Account/RegisterPasskey", async (PasskeyRegistrationRequest request, UserManager<ApplicationUser> userManager) =>
{
    var result = await userManager.AddPasskeyAsync(request.UserId, request.Name, request.Credential);
    return result.Succeeded ? Results.Ok() : Results.BadRequest(result.Errors);
});

app.Run();

[Authorize]
[Route("Account/[action]")]
public class AccountController : Controller
{
    private readonly UserManager<ApplicationUser> _userManager;

    public AccountController(UserManager<ApplicationUser> userManager)
    {
        _userManager = userManager;
    }

    public async Task<IActionResult> Passkeys()
    {
        var user = await _userManager.GetUserAsync(User);
        var passkeys = await _userManager.GetPasskeysAsync(user!);
        return View(passkeys);
    }

    [HttpPost]
    public async Task<IActionResult> RemovePasskey(string credentialId)
    {
        var user = await _userManager.GetUserAsync(User);
        var result = await _userManager.RemovePasskeyAsync(user!, credentialId);
        return result.Succeeded ? RedirectToAction(nameof(Passkeys)) : BadRequest();
    }
}
